namespace CourseCatalog.Models;

public class Department
{
    public int Id { get; set; }
    public string Code { get; set; } = string.Empty;
    public string Name { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
}

public class Course
{
    public int Id { get; set; }
    public int DepartmentId { get; set; }
    public string CourseCode { get; set; } = string.Empty;
    public string Title { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public int Credits { get; set; }
    public string Schedule { get; set; } = string.Empty;
    public string InstructorName { get; set; } = string.Empty;
    public string InstructorBio { get; set; } = string.Empty;
    public bool IsFeatured { get; set; }
    public string DepartmentName { get; set; } = string.Empty;
}

public class EnrollmentRequest
{
    public string StudentName { get; set; } = string.Empty;
    public string StudentId { get; set; } = string.Empty;
    public int CourseId { get; set; }
}

using CourseCatalog.Models;

namespace CourseCatalog.Services;

public class CatalogService
{
    private static readonly List<Department> Departments =
    [
        new() { Id = 1, Code = "CS", Name = "Computer Science", Description = "Study of computation, algorithms, and information systems." },
        new() { Id = 2, Code = "MATH", Name = "Mathematics", Description = "Study of numbers, structures, and patterns." },
        new() { Id = 3, Code = "ENG", Name = "English", Description = "Study of literature, writing, and language." },
        new() { Id = 4, Code = "PHYS", Name = "Physics", Description = "Study of matter, energy, and the fundamental forces of nature." },
        new() { Id = 5, Code = "HIST", Name = "History", Description = "Study of past events and human civilization." },
    ];

    private static readonly List<Course> Courses =
    [
        new() { Id = 1, DepartmentId = 1, CourseCode = "CS 101", Title = "Introduction to Programming", Description = "Learn the fundamentals of programming using Python. Covers variables, control flow, functions, and basic data structures.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", InstructorName = "Dr. Sarah Chen", InstructorBio = "Dr. Chen has 15 years of experience in software engineering and computer science education. She holds a PhD from MIT and has published extensively on programming pedagogy.", IsFeatured = true, DepartmentName = "Computer Science" },
        new() { Id = 2, DepartmentId = 1, CourseCode = "CS 201", Title = "Data Structures and Algorithms", Description = "Study of fundamental data structures (trees, graphs, hash tables) and algorithm design techniques (divide-and-conquer, dynamic programming).", Credits = 4, Schedule = "Tue/Thu 10:30 AM–12:00 PM", InstructorName = "Dr. James Park", InstructorBio = "Dr. Park specializes in algorithm optimization and competitive programming. Previously a senior engineer at Google.", IsFeatured = true, DepartmentName = "Computer Science" },
        new() { Id = 3, DepartmentId = 1, CourseCode = "CS 310", Title = "Database Systems", Description = "Relational database design, SQL, normalization, indexing, and transaction management.", Credits = 3, Schedule = "Mon/Wed 2:00–3:20 PM", InstructorName = "Dr. Maria Lopez", InstructorBio = "Dr. Lopez worked at Oracle for a decade before joining academia. Her research focuses on distributed database systems.", IsFeatured = false, DepartmentName = "Computer Science" },
        new() { Id = 4, DepartmentId = 2, CourseCode = "MATH 151", Title = "Calculus I", Description = "Limits, derivatives, and integrals of single-variable functions. Applications to physics and engineering.", Credits = 4, Schedule = "Mon/Wed/Fri 11:00–11:50 AM", InstructorName = "Dr. Robert Williams", InstructorBio = "Dr. Williams is an award-winning educator with a passion for making calculus accessible to all students.", IsFeatured = true, DepartmentName = "Mathematics" },
        new() { Id = 5, DepartmentId = 2, CourseCode = "MATH 220", Title = "Linear Algebra", Description = "Vector spaces, linear transformations, matrices, eigenvalues, and applications.", Credits = 3, Schedule = "Tue/Thu 1:00–2:20 PM", InstructorName = "Dr. Emily Zhang", InstructorBio = "Dr. Zhang researches applied mathematics and has consulted for aerospace companies on computational modeling.", IsFeatured = false, DepartmentName = "Mathematics" },
        new() { Id = 6, DepartmentId = 3, CourseCode = "ENG 101", Title = "Composition and Rhetoric", Description = "Develop clear, effective writing skills through essays, research papers, and peer workshops.", Credits = 3, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", InstructorName = "Prof. David Miller", InstructorBio = "Prof. Miller is a published author and writing coach with experience mentoring students from diverse backgrounds.", IsFeatured = false, DepartmentName = "English" },
        new() { Id = 7, DepartmentId = 3, CourseCode = "ENG 250", Title = "American Literature", Description = "Survey of American literary works from the colonial period to the present day.", Credits = 3, Schedule = "Tue/Thu 9:00–10:20 AM", InstructorName = "Dr. Angela Brooks", InstructorBio = "Dr. Brooks specializes in 20th-century American fiction and has received multiple teaching excellence awards.", IsFeatured = true, DepartmentName = "English" },
        new() { Id = 8, DepartmentId = 4, CourseCode = "PHYS 101", Title = "General Physics I", Description = "Mechanics, thermodynamics, and waves. Includes weekly lab sessions.", Credits = 4, Schedule = "Mon/Wed/Fri 1:00–1:50 PM + Thu Lab 2:00–4:00 PM", InstructorName = "Dr. Richard Feynman Jr.", InstructorBio = "Dr. Feynman Jr. brings physics to life with engaging demonstrations and real-world applications.", IsFeatured = false, DepartmentName = "Physics" },
        new() { Id = 9, DepartmentId = 4, CourseCode = "PHYS 220", Title = "Electromagnetism", Description = "Electric fields, magnetic fields, Maxwell's equations, and electromagnetic waves.", Credits = 4, Schedule = "Tue/Thu 11:00 AM–12:20 PM", InstructorName = "Dr. Lisa Nakamura", InstructorBio = "Dr. Nakamura's research in plasma physics has been funded by NASA and the Department of Energy.", IsFeatured = false, DepartmentName = "Physics" },
        new() { Id = 10, DepartmentId = 5, CourseCode = "HIST 101", Title = "World History to 1500", Description = "Survey of major civilizations, trade routes, and cultural exchanges from antiquity through the medieval period.", Credits = 3, Schedule = "Mon/Wed 3:00–4:20 PM", InstructorName = "Dr. Thomas Grant", InstructorBio = "Dr. Grant is an archaeologist and historian who has led excavations in the Mediterranean and Middle East.", IsFeatured = false, DepartmentName = "History" },
        new() { Id = 11, DepartmentId = 5, CourseCode = "HIST 205", Title = "Modern European History", Description = "From the French Revolution through the Cold War: political, social, and intellectual transformations.", Credits = 3, Schedule = "Tue/Thu 3:00–4:20 PM", InstructorName = "Dr. Claire Dubois", InstructorBio = "Dr. Dubois holds dual appointments in History and Political Science, with expertise in 19th-century European diplomacy.", IsFeatured = true, DepartmentName = "History" },
    ];

    public List<Department> GetDepartments() => Departments;

    public Department? GetDepartment(int id) => Departments.FirstOrDefault(d => d.Id == id);

    public List<Course> GetAllCourses() => Courses;

    public List<Course> GetFeaturedCourses() => Courses.Where(c => c.IsFeatured).ToList();

    public List<Course> GetCoursesByDepartment(int departmentId) =>
        Courses.Where(c => c.DepartmentId == departmentId).ToList();

    public List<Course> SearchCourses(string? query, int? departmentId)
    {
        var results = Courses.AsEnumerable();

        if (departmentId.HasValue && departmentId.Value > 0)
            results = results.Where(c => c.DepartmentId == departmentId.Value);

        if (!string.IsNullOrWhiteSpace(query))
        {
            var q = query.Trim().ToLowerInvariant();
            results = results.Where(c =>
                c.Title.Contains(q, StringComparison.OrdinalIgnoreCase) ||
                c.CourseCode.Contains(q, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(q, StringComparison.OrdinalIgnoreCase) ||
                c.InstructorName.Contains(q, StringComparison.OrdinalIgnoreCase));
        }

        return results.ToList();
    }

    public Course? GetCourse(int id) => Courses.FirstOrDefault(c => c.Id == id);

    public bool SubmitEnrollmentRequest(EnrollmentRequest request)
    {
        // In a real app, this would persist to a database
        return !string.IsNullOrWhiteSpace(request.StudentName)
            && !string.IsNullOrWhiteSpace(request.StudentId)
            && request.CourseId > 0
            && Courses.Any(c => c.Id == request.CourseId);
    }
}

