@page "/"
@using CourseCatalog.Services
@using CourseCatalog.Models
@inject CatalogService Catalog

<PageTitle>University Course Catalog</PageTitle>

<h1>University Course Catalog</h1>
<p class="lead">Welcome to the course catalog. Browse departments, search for courses, or submit an enrollment request.</p>

<h2>Featured Courses</h2>
<div class="row">
    @foreach (var course in featuredCourses)
    {
        <div class="col-md-6 col-lg-4 mb-3">
            <div class="card h-100">
                <div class="card-body">
                    <h5 class="card-title">@course.CourseCode</h5>
                    <h6 class="card-subtitle mb-2 text-muted">@course.Title</h6>
                    <p class="card-text">@course.Credits credits &bull; @course.DepartmentName</p>
                    <a href="/courses/@course.Id" class="card-link">View Details</a>
                </div>
            </div>
        </div>
    }
</div>

<h2 class="mt-4">Departments</h2>
<div class="list-group">
    @foreach (var dept in departments)
    {
        <a href="/courses?departmentId=@dept.Id" class="list-group-item list-group-item-action">
            <strong>@dept.Code</strong> &mdash; @dept.Name
            <br /><small class="text-muted">@dept.Description</small>
        </a>
    }
</div>

<div class="mt-4">
    <a href="/courses" class="btn btn-primary me-2">Browse All Courses</a>
    <a href="/enroll" class="btn btn-outline-primary">Enroll in a Course</a>
</div>

@code {
    private List<Course> featuredCourses = [];
    private List<Department> departments = [];

    protected override void OnInitialized()
    {
        featuredCourses = Catalog.GetFeaturedCourses();
        departments = Catalog.GetDepartments();
    }
}

@page "/courses"
@using CourseCatalog.Services
@using CourseCatalog.Models
@inject CatalogService Catalog

<PageTitle>Course Catalog - Browse Courses</PageTitle>

<h1>Browse Courses</h1>

<form method="get" action="/courses" class="row g-3 mb-4">
    <div class="col-md-6">
        <label for="query" class="form-label">Search</label>
        <input type="text" class="form-control" id="query" name="query" value="@Query"
               placeholder="Search by title, code, or instructor..." />
    </div>
    <div class="col-md-4">
        <label for="departmentId" class="form-label">Department</label>
        <select class="form-select" id="departmentId" name="departmentId">
            <option value="">All Departments</option>
            @foreach (var dept in departments)
            {
                <option value="@dept.Id" selected="@(DepartmentId == dept.Id)">@dept.Name</option>
            }
        </select>
    </div>
    <div class="col-md-2 d-flex align-items-end">
        <button type="submit" class="btn btn-primary w-100">Filter</button>
    </div>
</form>

@if (courses.Count == 0)
{
    <div class="alert alert-info">No courses found matching your criteria.</div>
}
else
{
    <p class="text-muted">Showing @courses.Count course(s)</p>
    <div class="table-responsive">
        <table class="table table-striped table-hover">
            <thead>
                <tr>
                    <th>Code</th>
                    <th>Title</th>
                    <th>Department</th>
                    <th>Credits</th>
                    <th>Instructor</th>
                    <th></th>
                </tr>
            </thead>
            <tbody>
                @foreach (var course in courses)
                {
                    <tr>
                        <td>@course.CourseCode</td>
                        <td>@course.Title</td>
                        <td>@course.DepartmentName</td>
                        <td>@course.Credits</td>
                        <td>@course.InstructorName</td>
                        <td><a href="/courses/@course.Id">Details</a></td>
                    </tr>
                }
            </tbody>
        </table>
    </div>
}

@code {
    [SupplyParameterFromQuery]
    public string? Query { get; set; }

    [SupplyParameterFromQuery]
    public int? DepartmentId { get; set; }

    private List<Course> courses = [];
    private List<Department> departments = [];

    protected override void OnInitialized()
    {
        departments = Catalog.GetDepartments();
        courses = Catalog.SearchCourses(Query, DepartmentId);
    }
}

@page "/enroll"
@using CourseCatalog.Services
@using CourseCatalog.Models
@inject CatalogService Catalog

<PageTitle>Enrollment Request</PageTitle>

<h1>Enrollment Request</h1>
<p>Fill out the form below to submit an enrollment request.</p>

@if (submitted)
{
    <div class="alert alert-success">
        <strong>Success!</strong> Your enrollment request has been submitted. You will receive a confirmation via your university email.
    </div>
    <a href="/courses">Browse more courses</a>
}
else
{
    @if (error)
    {
        <div class="alert alert-danger">
            Please fill in all required fields and select a valid course.
        </div>
    }

    <form method="post" class="col-md-6">
        <AntiforgeryToken />
        <div class="mb-3">
            <label for="studentName" class="form-label">Full Name <span class="text-danger">*</span></label>
            <input type="text" class="form-control" id="studentName" name="Model.StudentName"
                   value="@Model.StudentName" required />
        </div>
        <div class="mb-3">
            <label for="studentId" class="form-label">Student ID <span class="text-danger">*</span></label>
            <input type="text" class="form-control" id="studentId" name="Model.StudentId"
                   value="@Model.StudentId" required />
        </div>
        <div class="mb-3">
            <label for="courseId" class="form-label">Course <span class="text-danger">*</span></label>
            <select class="form-select" id="courseId" name="Model.CourseId" required>
                <option value="0">-- Select a course --</option>
                @foreach (var course in courses)
                {
                    <option value="@course.Id" selected="@(Model.CourseId == course.Id)">
                        @course.CourseCode - @course.Title
                    </option>
                }
            </select>
        </div>
        <button type="submit" class="btn btn-primary">Submit Enrollment Request</button>
        <a href="/courses" class="btn btn-link">Cancel</a>
    </form>
}

@code {
    [SupplyParameterFromForm]
    public EnrollmentRequest Model { get; set; } = new();

    [SupplyParameterFromQuery]
    public int? CourseId { get; set; }

    private List<Course> courses = [];
    private bool submitted;
    private bool error;

    protected override void OnInitialized()
    {
        courses = Catalog.GetAllCourses();

        // Pre-select course from query string
        if (CourseId.HasValue && Model.CourseId == 0)
        {
            Model.CourseId = CourseId.Value;
        }
    }

    protected override void OnParametersSet()
    {
        // Handle form POST
        if (HttpMethods.IsPost(HttpContext.Request.Method))
        {
            if (Catalog.SubmitEnrollmentRequest(Model))
            {
                submitted = true;
            }
            else
            {
                error = true;
            }
        }
    }

    [CascadingParameter]
    public HttpContext HttpContext { get; set; } = default!;
}

